async function publishProject(){if(!state.account){openModal();toast('Sign in to publish');return}try{await ensureProject()}catch(e){toast(e.message);return}termCmd('deploy '+state.project.name);const btn=q('#publishBtn');btn.disabled=true;try{const d=await api('/projects/'+encodeURIComponent(state.project.id)+'/deploy',{method:'POST',body:'{}'});termOut('Published: '+(d.url||d.message||'ok'));toast(d.message||'Static site published');termLine([{cls:'t-ok',text:'→ '+(d.url||'done')}])}catch(e){termErr(e.message);toast(e.message)}finally{btn.disabled=false}}
